import React, { useEffect, useState } from 'react';
import { getProduct, getSeller, postSellerVisit } from '../services/api';

export default function ProductPageInner({ id }) {
  const [p, setP] = useState(null);
  const [seller, setSeller] = useState(null);

  useEffect(() => {
    (async () => {
      const prod = await getProduct(id);
      setP(prod);
      if (prod?.seller?.id) setSeller(await getSeller(prod.seller.id));
    })();
  }, [id]);

  if (!p) return <div className="loading">Cargando…</div>;

  const goSeller = async () => {
    if (p?.seller?.id) {
      await postSellerVisit(p.seller.id);
      // navegamos al perfil interno del vendedor
      window.location.href = `/negocio/${p.seller.id}`;
    }
  };

  const goBack = () => window.history.length > 1 ? window.history.back() : (window.location.href = '/');

  const priceLabel =
    typeof p.price === 'number'
      ? new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS', maximumFractionDigits: 0 }).format(p.price)
      : '';

  return (
    <div className="pp-wrap">
      {/* Header con logo + título */}
      <header className="pp-header">
        <div className="pp-logo">
          <img src="/logo.png" alt="Conecta Pinamar" />
        </div>
        <h1 className="pp-title">producto</h1>
      </header>

      {/* Contenido principal */}
      <main className="pp-main">
        <figure className="pp-card">
          <img src={p.imageUrl || '/placeholder.png'} alt={p.name} />
        </figure>

        <div className="pp-price">{priceLabel || '$0000'}</div>

        <div className="pp-actions">
          <button className="pp-btn pp-btn-primary" onClick={goSeller}>LO QUIERO!</button>
          <button className="pp-btn pp-btn-secondary" onClick={goSeller}>Ir a pagina del vendedor</button>
        </div>

        {p.description && <p className="pp-desc">{p.description}</p>}

        <button className="pp-back" onClick={goBack}>← volver a la pagina anterior</button>
      </main>

      {/* CSS en el mismo archivo */}
      <style>{`
        :root{
          --cp-yellow:#F7D34A;
          --cp-black:#0c0c0c;
          --cp-bg:#fff;
          --cp-text:#111;
          --cp-muted:#6b7280;
        }
        .loading{padding:32px;text-align:center}

        .pp-wrap{
          background: var(--cp-bg);
          color: var(--cp-text);
          min-height: 100dvh;
          display:flex;
          flex-direction:column;
          align-items:center;
        }

        /* Header */
        .pp-header{
          width:100%;
          max-width:960px;
          padding:16px 12px 0 12px;
        }
        .pp-logo img{
          height:34px;
          display:block;
        }
        .pp-title{
          margin:8px 0 0 0;
          font-size: clamp(32px, 8vw, 56px);
          line-height: 1.05;
          font-weight: 800;
          text-transform: lowercase;
        }

        /* Main */
        .pp-main{
          width:100%;
          max-width:960px;
          padding:16px 12px 40px 12px;
          display:flex;
          flex-direction:column;
          align-items:center;
          gap:18px;
        }

        .pp-card{
          margin:8px 0 0 0;
          width: min(560px, 92vw);
          background:#fff;
          border-radius: 20px;
          box-shadow: 0 8px 30px rgba(0,0,0,.12);
          overflow: hidden;
          padding: 0;
        }
        .pp-card img{
          display:block;
          width:100%;
          height:auto;
          aspect-ratio: 1 / 1;
          object-fit: cover;
        }

        .pp-price{
          font-size: clamp(36px, 10vw, 56px);
          font-weight: 900;
          letter-spacing: .5px;
        }

        .pp-actions{
          display:flex;
          flex-direction:column;
          gap:12px;
          width:min(420px, 92vw);
        }

        .pp-btn{
          appearance:none;
          border:0;
          border-radius: 12px;
          padding: 14px 18px;
          font-size: clamp(16px, 3.8vw, 20px);
          font-weight: 800;
          cursor:pointer;
          width:100%;
        }
        .pp-btn-primary{
          background: var(--cp-yellow);
          color: #111;
          box-shadow: 0 8px 0 #e3bf32 inset;
        }
        .pp-btn-primary:active{ transform: translateY(1px); }

        .pp-btn-secondary{
          background: #fff;
          color:#111;
          border: 2px solid var(--cp-yellow);
        }

        .pp-desc{
          margin: 6px 0 0 0;
          color: var(--cp-muted);
          max-width: 680px;
          text-align:center;
        }

        .pp-back{
          margin-top: 12px;
          background: transparent;
          border: 0;
          color: #6b7280;
          font-size: 12px;
          cursor: pointer;
        }

        @media (min-width: 768px){
          .pp-actions{ gap:14px; }
        }
      `}</style>
    </div>
  );
}
